<?php $title='Proteção e resgate de '.$pet['name']; ?>
<?php if(!$case):?><section class="lost-control safe"><div><span class="big-icon">🛡</span><span class="eyebrow">Tudo seguro</span><h2><?=e($pet['name'])?> não está em modo perdido.</h2><p>Ative somente em uma emergência real. O perfil público muda, o sistema registra o caso e prepara alertas.</p></div><form method="post" action="<?=url('/owner/pets/'.$pet['id'].'/lost/activate')?>" class="lost-form"><?=csrf_field()?><label>Última vez visto em<input type="datetime-local" name="last_seen_at"></label><label>Endereço ou referência<input name="last_seen_address" placeholder="Praia, rua, praça..."></label><label>Cidade<input name="last_seen_city" value="<?=e($pet['city'])?>"></label><div class="form-grid"><label>Latitude<input name="latitude"></label><label>Longitude<input name="longitude"></label></div><button class="btn btn-soft" type="button" data-fill-location>📍 Usar localização atual</button><label>Descrição<textarea name="description" rows="3"></textarea></label><label>Mensagem pública<textarea name="public_message" rows="3" placeholder="Como as pessoas devem agir?"></textarea></label><div class="form-grid"><label>Raio de alerta<select name="radius_km"><option>1</option><option>3</option><option selected>5</option><option>10</option></select></label><label>Recompensa (R$)<input type="number" step="0.01" name="reward" value="<?=e((int)$pet['reward_cents']/100)?>"></label></div><button class="btn btn-danger btn-block" onclick="return confirm('Ativar modo perdido para <?=e($pet['name'])?>?')">🚨 Ativar modo perdido</button></form></section><?php else:?><section class="lost-control active"><div><span class="status danger large">🚨 MODO PERDIDO ATIVO</span><h2>A rede está procurando por <?=e($pet['name'])?>.</h2><p><?=e($case['public_message']?:$case['description'])?></p><p><b>Última região:</b> <?=e($case['last_seen_address'])?> · <?=e($case['last_seen_city'])?></p><a class="btn btn-light" target="_blank" href="<?=public_pet_url($pet)?>">Ver perfil de emergência</a></div><form method="post" action="<?=url('/owner/pets/'.$pet['id'].'/lost/resolve')?>"><?=csrf_field()?><button class="btn btn-success" onclick="return confirm('Confirmar que <?=e($pet['name'])?> voltou para casa?')">💚 Marcar como encontrado</button></form></section><section class="dashboard-section"><div class="section-row"><div><h2>Avistamentos recebidos</h2><p>Cada pessoa pode enviar localização, mensagem e foto sem instalar aplicativo.</p></div><span class="badge"><?=count($sightings)?></span></div><div class="timeline"><?php foreach($sightings as $item):?><article><span>📍</span><div><h3><?=e($item['reporter_name']?:'Pessoa anônima')?></h3><p><?=e($item['message'])?></p><small><?=e($item['created_at'])?> · <?=e($item['latitude'].', '.$item['longitude'])?></small><?php if($item['photo_path']):?><img class="sighting-photo" src="<?=asset($item['photo_path'])?>" alt=""><?php endif;?></div></article><?php endforeach;?><?php if(!$sightings):?><div class="empty-state"><span>👀</span><p>Ainda não há avistamentos. Compartilhe o perfil de emergência.</p></div><?php endif;?></div></section><?php endif;?>
